{
    return getReportProperty (properties, type, key, allowBlank, trim, null);
}

private static String getReportProperty (final IProperties properties, final String type, final String key, final boolean allowBlank, final boolean trim, final String dflt)
{
    if ($assert.ENABLED) $assert.ASSERT (properties != null, "null input: properties");
    if ($assert.ENABLED) $assert.ASSERT (key != null, "null input: key");

    String result = properties.getProperty (IReportProperties.PREFIX.concat (type).concat (".").concat (key), dflt);

    if (! allowBlank && (result != null) && (result.trim ().length () == 0))
        return dflt;
    else
    {
        if (trim && (result != null))
        {
            result = result.trim ();
        }

        return result;
    }
}


